<?php

namespace Tests\Unit;

use App\Kernel\Crypto\BlindIndex;
use App\Kernel\Crypto\CryptoException;
use App\Kernel\Crypto\FieldCipher;
use App\Kernel\Security\JwtService;
use App\Kernel\Security\Passwords;
use Firebase\JWT\ExpiredException;
use PHPUnit\Framework\TestCase;

/**
 * Proves wire-compatibility with the FastAPI kernel using vectors generated by the Python reference
 * (tests/fixtures/generate_vectors.py) and, when the reference virtualenv exists, in the opposite direction.
 */
class InteropTest extends TestCase
{
    /** @var array<string, mixed> */
    private array $v;

    protected function setUp(): void
    {
        $this->v = json_decode((string) file_get_contents(__DIR__.'/../fixtures/python_vectors.json'), true, 512, JSON_THROW_ON_ERROR);
    }

    private function cipher(): FieldCipher
    {
        return new FieldCipher(array_map('strval', $this->v['keys']), 1);
    }

    public function test_decrypts_envelopes_produced_by_python(): void
    {
        foreach ($this->v['envelopes'] as $case) {
            $this->assertSame($case['plaintext'], $this->cipher()->decrypt($case['envelope']), 'envelope v'.$case['version']);
            $this->assertSame($case['version'], $this->cipher()->envelopeVersion($case['envelope']));
        }
    }

    public function test_envelope_format_and_roundtrip(): void
    {
        $envelope = $this->cipher()->encrypt('admin@example.com');
        $this->assertMatchesRegularExpression('/^v1:[A-Za-z0-9+\/=]{16}:[A-Za-z0-9+\/=]+$/', (string) $envelope);
        [, $nonce, $blob] = explode(':', (string) $envelope);
        $this->assertSame(12, strlen((string) base64_decode($nonce, true)));
        $this->assertSame(strlen('admin@example.com') + 16, strlen((string) base64_decode($blob, true)), 'ciphertext||16-byte tag');
        $this->assertSame('admin@example.com', $this->cipher()->decrypt($envelope));
        $this->assertNotSame($envelope, $this->cipher()->encrypt('admin@example.com'), 'random nonce');
        $this->assertNull($this->cipher()->encrypt(null));
    }

    public function test_tampered_or_unknown_key_envelopes_are_rejected(): void
    {
        $envelope = (string) $this->cipher()->encrypt('secret');
        $parts = explode(':', $envelope);
        $blob = (string) base64_decode($parts[2], true);
        $blob[0] = $blob[0] ^ "\x01";
        $this->expectException(CryptoException::class);
        $this->cipher()->decrypt($parts[0].':'.$parts[1].':'.base64_encode($blob));
    }

    public function test_unknown_key_version_is_rejected(): void
    {
        $this->expectException(CryptoException::class);
        $this->cipher()->decrypt('v9:AAAAAAAAAAAAAAAA:AAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAA');
    }

    public function test_blind_index_matches_python(): void
    {
        $index = new BlindIndex($this->v['pepper']);
        foreach ($this->v['blind_index'] as $case) {
            $this->assertSame($case['hash'], $index->compute($case['input']));
        }
        $this->assertNull($index->compute(''));
        $this->assertSame($index->compute('A@B.COM'), $index->compute('  a@b.com '));
    }

    public function test_decodes_jwts_signed_by_python(): void
    {
        $jwt = new JwtService($this->v['jwt_secret']);
        $claims = $jwt->decode($this->v['jwt']['access']);
        $this->assertSame($this->v['jwt']['claims']['sub'], $claims['sub']);
        $this->assertSame('access', $claims['type']);
        $this->assertSame(3, $claims['token_version']);
        $this->assertTrue($claims['is_super_admin']);
        $this->assertSame('password_reset', $jwt->decode($this->v['jwt']['reset'])['type']);
    }

    public function test_expired_and_wrongly_signed_jwts_are_rejected(): void
    {
        $jwt = new JwtService($this->v['jwt_secret']);
        try {
            $jwt->decode($this->v['jwt']['expired']);
            $this->fail('expired token accepted');
        } catch (ExpiredException) {
            $this->addToAssertionCount(1);
        }
        $this->expectException(\Throwable::class);
        (new JwtService('another-secret-key-that-is-long-enough-00'))->decode($this->v['jwt']['access']);
    }

    public function test_verifies_python_bcrypt_hashes(): void
    {
        $passwords = new Passwords(4);
        foreach ($this->v['bcrypt'] as $case) {
            $this->assertStringStartsWith('$2b$12$', $case['hash']);
            $this->assertTrue($passwords->verify($case['password'], $case['hash']));
            // bcrypt only considers the first 72 bytes, so the negative check applies to shorter passwords only.
            if (strlen($case['password']) < 72) {
                $this->assertFalse($passwords->verify($case['password'].'x', $case['hash']));
            }
        }
        $this->assertFalse($passwords->verify('x', ''));
    }

    public function test_php_artifacts_verify_in_python(): void
    {
        $python = dirname(__DIR__, 4).'/apps/api-server/.venv/bin/python';
        if (! is_file($python)) {
            $this->markTestSkipped('Python reference virtualenv not available.');
        }
        $cipher = $this->cipher();
        $secret = $this->v['jwt_secret'];
        $jwt = new JwtService($secret);
        $passwords = new Passwords(4);
        $payload = [
            'keys' => $this->v['keys'],
            'pepper' => $this->v['pepper'],
            'jwt_secret' => $secret,
            'envelope' => $cipher->encrypt('php-written@example.com'),
            'envelope_v2' => $cipher->encrypt('php-written-v2@example.com', 2),
            'blind' => (new BlindIndex($this->v['pepper']))->compute(' PHP@Example.com '),
            'access' => $jwt->createAccessToken(['sub' => 'abc', 'email' => 'x@y.z', 'token_version' => 7, 'is_super_admin' => false]),
            'reset' => $jwt->createResetToken('abc', 7),
            'bcrypt' => $passwords->hash('php-Passw0rd!'),
        ];
        $file = tempnam(sys_get_temp_dir(), 'php-artifacts');
        file_put_contents($file, json_encode($payload));

        $script = __DIR__.'/../fixtures/verify_php_artifacts.py';
        $output = [];
        $code = 0;
        exec(escapeshellarg($python).' -I '.escapeshellarg($script).' '.escapeshellarg($file).' 2>&1', $output, $code);
        @unlink($file);

        $this->assertSame(0, $code, implode("\n", $output));
    }
}
